using System;using System.Globalization;using ForteMove.Models.Scheduling;using ForteMove.Web.Infrastructure;
namespace ForteMove.Web.Driver{public partial class Today:DriverPage{protected void Page_Load(object sender,EventArgs e){if(!IsPostBack)Bind();}private void Bind(){var items=ServiceFactory.CreateDriverOperationsService().GetToday(CurrentPrincipalContext.UserAccountId);rptTrips.DataSource=items;rptTrips.DataBind();pnlEmpty.Visible=items.Count==0;}protected string FormatTime(object value){return DateTime.Today.Add((TimeSpan)value).ToString("HH:mm",CultureInfo.CurrentCulture);}protected string FormatStatus(object value){return Convert.ToString(value).Replace("InProgress","In progress");}protected string StatusClass(object value){string status=Convert.ToString(value);return status=="Completed"?"status-badge status-success":status=="Delayed"?"status-badge status-warning":status=="Cancelled"?"status-badge status-neutral":"status-badge status-info";}protected string Overdue(object value){return Convert.ToBoolean(value)?"Departure passed - Trip not started":string.Empty;}}}
